const TEMPLATE = "*{frase}*\n\n{productname}\n\nDe ~R$ {priceoriginal}~ ❌\nPor *R$ {price}* ✅ ({pricediscountrate}% OFF)\n\nLoja Oficial {shopname}\n🔗{offerlink}";
const ROBO_ID = "badb8e7b-0d66-46eb-8aa6-34d173155128";
