const DEDUPE_VERSION = 1;
const HORARIOS_PADRAO = {"dom":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"qua":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"qui":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"sab":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"seg":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"sex":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15},"ter":{"fim":"20:00","inicio":"09:00","enabled":true,"intervalo":15}};

const MAX_TENTATIVAS_ENVIO = 3; // depois disso o produto é descartado pra não travar a fila

const http = this.helpers.httpRequest;
const sd = $getWorkflowStaticData("global");
sd.fails = sd.fails || {};
// Reseta historico local se o robo foi editado (DEDUPE_VERSION muda a cada save).
