    await apiPost({
      action: "record_sent_product", robo_id: ROBO_ID, table_id: TABLE_ID,
      row_id: item && item.id, productname: item && item.productname, offerlink: item && item.offerlink,
      link_compra: item && item.link_compra, imageUrl: item && item.imageUrl, destino: grupo,
    });
