}

// ---- Similaridade (CORRIGIDA) ----
function normProduto(v) {
  return String(v || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/https?:\/\/\S+/g, " ").replace(/[^a-z0-9]+/g, " ").trim().replace(/\s+/g, " ");
}
function productId(item) {
  const s = [item && item.link_compra, item && item.offerlink, item && item.imageUrl].map(x => String(x || "")).join(" ");
  const plat = String(PLATAFORMA || "").toLowerCase();
  if (plat.includes("mercado")) {
    const m = s.match(/\b(MLB(?:U)?\d{6,})\b/i) || s.match(/\/p\/(MLB\d{6,})/i);
    return m && m[1] ? m[1].toUpperCase() : "";
  }
  if (plat.includes("shopee")) {
    let m = s.match(/[-.\/]i\.(\d{3,})\.(\d{3,})/i);
    if (m) return "SHOPEE:" + m[1] + "." + m[2];
    const item_id = (s.match(/[?&]item_id=(\d{3,})/i) || [])[1];
    const shop_id = (s.match(/[?&]shop_id=(\d{3,})/i) || [])[1];
    if (item_id) return "SHOPEE:" + (shop_id || "0") + "." + item_id;
    // fallback: shortlink shopee (s.shopee.com.br/XXXX) — usa o proprio link como id
    const short = (String((item && item.offerlink) || "").match(/shopee[^\s]*/i) || [])[0]
               || (String((item && item.link_compra) || "").match(/shopee[^\s]*/i) || [])[0];
    return short ? "SHOPEE_URL:" + short.toLowerCase() : "";
  }
  return "";
}
function mlProductId(item) { return productId(item); }
const STOP_PROD = new Set(["de","da","do","das","dos","com","sem","para","pra","por","em","no","na","nos","nas","e","ou","a","o","as","os","um","uma","uns","umas","kit","set","pcs","un","und","ml","cm","mm","kg","g","mah","w","v","volts","cor"]);
function prodTokens(v) { return normProduto(v).split(" ").filter(t => t.length >= 3 && !STOP_PROD.has(t)); }
function produtoSimilar(a, b) {
  const ida = mlProductId(a), idb = mlProductId(b);
  if (ida && idb && ida === idb) return true;        // mesmo produto = única trava forte
  // fora do ML: se NAO temos id, so bloqueia se o link/offerlink/link_compra bater exato.
  // Nao usa jaccard de titulo (gerava falsos positivos massivos na Shopee, ex.: mesma
  // camiseta em tamanhos diferentes derrubava tudo).
  const isML = /mercado/i.test(String(PLATAFORMA || ""));
  if (!isML) {
    const norm = (v) => String(v || "").trim().toLowerCase();
    const linksA = [norm(a && a.offerlink), norm(a && a.link_compra)].filter(Boolean);
    const linksB = [norm(b && b.offerlink), norm(b && b.link_compra)].filter(Boolean);
    for (const la of linksA) if (linksB.includes(la)) return true;
    // Fora do ML NAO existe similaridade difusa de titulo: com titulos genericos da
    // Shopee o jaccard queimava ~98% da tabela e o robo dizia "nenhum produto enviavel".
    // Identidade forte apenas: titulo normalizado IDENTICO.
    const ta = normProduto(a && a.productname), tb = normProduto(b && b.productname);
    if (ta && tb && ta === tb) return true;
    return false;
  }
  const at = new Set(prodTokens(a && a.productname));
  const bt = new Set(prodTokens(b && b.productname));
  if (!at.size || !bt.size) return false;
  let inter = 0; for (const t of at) if (bt.has(t)) inter++;
  const union = at.size + bt.size - inter;
  const jac = union > 0 ? inter / union : 0;
  return jac >= 0.8;
}
let sentHistory = [];
function localJaFoiEnviado(item) { return sentHistory.some(sent => produtoSimilar(item, sent)); }

function toMin(t) { const p = String(t || "00:00").split(":"); return (parseInt(p[0]||"0",10)*60) + parseInt(p[1]||"0",10); }

async function patchRow(idRow, data) {
  try {
    await http({
      method: "PATCH", url: `${N8N_BASE}/data-tables/${TABLE_ID}/rows/update`,
      headers: { "X-N8N-API-KEY": N8N_KEY, "Content-Type": "application/json" },
      body: { filter: { type: "and", filters: [{ columnName: "id", condition: "eq", value: idRow }] }, data },
      json: true,
    });
  } catch (_) {}
}
async function queimaRow(idRow) { await patchRow(idRow, { sending: true, sent_at: new Date().toISOString() }); }

// 0. Horário/intervalo FIXOS neste nó (não consulta o sistema/Lovable):
//    09:00–20:00 (São Paulo), 1 produto a cada 15 min, todos os dias.
const horarios = HORARIOS_PADRAO;

// 1. Hora atual em São Paulo
const nowUtc = new Date();
const parts = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/Sao_Paulo", hour12: false, weekday: "short", hour: "2-digit", minute: "2-digit",
}).formatToParts(nowUtc);
const wd = (parts.find(p => p.type === "weekday")?.value || "").toLowerCase().slice(0,3);
const wdMap = { sun: "dom", mon: "seg", tue: "ter", wed: "qua", thu: "qui", fri: "sex", sat: "sab" };
const diaKey = wdMap[wd] || "seg";
const hh = parseInt(parts.find(p => p.type === "hour")?.value || "0", 10);
const mm = parseInt(parts.find(p => p.type === "minute")?.value || "0", 10);
const minutosAgora = hh * 60 + mm;

// 2. Janela do dia
const cfg = horarios[diaKey];
if (!cfg || !cfg.enabled) return [{ json: { skipped: "dia desativado", dia: diaKey } }];
const ini = toMin(cfg.inicio), fim = toMin(cfg.fim);
if (minutosAgora < ini || minutosAgora > fim) {
  return [{ json: { skipped: "fora do horario", dia: diaKey, hora: hh+":"+String(mm).padStart(2,"0"), janela: cfg.inicio+"-"+cfg.fim } }];
}
const intervaloMin = Math.max(1, Number(cfg.intervalo) || 30);

// 3. Histórico recente (sending=true, últimos 45d) — usado p/ dedupe local, rodízio e INTERVALO
const COL_CATEGORIA = "categoria";
const normCat = (c) => String(c == null ? "" : c).trim().toLowerCase();
let ultimaCat = null, maxSentMs = 0;
try {
  const cutoff45 = new Date(nowUtc.getTime() - 45*24*60*60000).toISOString();
  // INTERVALO usa a janela cheia de 45d (robusto, NAO depende de staticData). O baseline
  // limpo do dedupe e aplicado DEPOIS, so na deduplicacao — nunca no calculo do intervalo.
  const filtroSent = { type: "and", filters: [
    { columnName: "sending", condition: "eq", value: true },
    { columnName: "sent_at", condition: "gte", value: cutoff45 },
  ] };
  let sentResp;
  try {
    sentResp = await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs:{ filter: JSON.stringify(filtroSent), sortBy:"sent_at:DESC", limit:250 }, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  } catch (_) {
    sentResp = await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs:{ filter: JSON.stringify(filtroSent), limit:250 }, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  }
  sentHistory = (sentResp && sentResp.data) ? sentResp.data : [];
  if (!Array.isArray(sentHistory)) sentHistory = [];
  // Linhas com sent_at começando por "__" (__CLAIM__ / __DEDUPE__) NAO foram envios
  // reais — nao podem entrar no dedupe de 45d, senao bloqueiam produto legitimo.
  // (O calculo de intervalo abaixo ja ignora datas invalidas, entao segue igual.)
  const _histReal = sentHistory.filter(r => !String((r && r.sent_at) || "").trim().startsWith("__"));
  let maisRecente = null;
  for (const r of sentHistory) {
    const t = Date.parse(String(r && r.sent_at || "")); // tokens de claim não são data válida → ignorados
    if (Number.isFinite(t)) {
      if (t > maxSentMs) maxSentMs = t;
      if (!maisRecente || t > maisRecente.t) maisRecente = { t, cat: normCat(r[COL_CATEGORIA]) };
    }
  }
  if (maisRecente) ultimaCat = maisRecente.cat;
  sentHistory = _histReal;
  // maxSentMs (intervalo) ja calculado com a janela cheia acima. Agora o DEDUPE passa a
  // ignorar o que e anterior ao baseline (queima antiga envenenada). Sem mais blast por reset.
  // NAO filtra mais por DEDUPE_DESDE_MS: static data do n8n e zerado a cada re-import
  // do workflow, e isso fazia o historico virar vazio => reenvio em massa. A janela de
  // 45 dias vale sempre. (DEDUPE_DESDE_MS segue existindo so p/ fails/intervalo.)
} catch (_) {}

// 4. Intervalo (15 min) — baseado no ÚLTIMO ENVIO REAL (staticData), usando o sent_at
//    mais recente da tabela apenas como base na primeira execução após o deploy.
const lastSendMs = Math.max(Number(sd.lastSentMs) || 0, maxSentMs);
if (lastSendMs > 0) {
  const diffMs = nowUtc.getTime() - lastSendMs;
  if (diffMs < intervaloMin * 60000) {
    return [{ json: { skipped: "intervalo nao atingido", faltam_min: Math.ceil((intervaloMin*60000 - diffMs)/60000) } }];
  }
}

// 5. Produtos disponíveis (sending=false)
// O filtro sending eq false do servidor NAO retorna linhas com sending nulo/vazio,
// por isso o robo dizia "sem produto novo" com a tabela cheia. Busca com filtro e,
// se vier 0, busca sem filtro — a selecao final e feita em codigo.
const filterObj = { type: "and", filters: [{ columnName: "sending", condition: "eq", value: false }] };
async function buscarRows(comFiltro) {
  const qsBase = comFiltro ? { filter: JSON.stringify(filterObj) } : {};
  try {
    return await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs:{ ...qsBase, sortBy:"id:DESC", limit:200 }, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  } catch (_) {
    return await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs:{ ...qsBase, limit:200 }, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  }
}
const isMLFetch = /mercado/i.test(String(PLATAFORMA || ""));
async function buscarPagina(cursor) {
  const qs = { filter: JSON.stringify(filterObj), limit: 200 };
  if (cursor) qs.cursor = cursor;
  try {
    return await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  } catch (_) {
    const qs2 = { limit: 200 };
    if (cursor) qs2.cursor = cursor;
    return await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
      qs: qs2, headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  }
}
let rowsData = await buscarRows(true);
let brutos = (rowsData && rowsData.data) ? rowsData.data : [];
if (!Array.isArray(brutos) || brutos.length === 0) {
  rowsData = await buscarRows(false);
  brutos = (rowsData && rowsData.data) ? rowsData.data : [];
  if (!Array.isArray(brutos)) brutos = [];
}
// Fora do ML: a tabela acumula milhares de linhas e os produtos realmente novos ficam
// espalhados no meio (o scraper re-insere os mesmos titulos toda hora). Ler so as 200
// primeiras fazia o robo dizer "nenhum produto enviavel" com produto novo na tabela.
// Varre a tabela em paginas (cursor) ate 5000 linhas. ML fica exatamente como estava.
if (!isMLFetch) {
  let cursor = (rowsData && rowsData.nextCursor) || null;
  let guard = 0;
  while (cursor && brutos.length < 5000 && guard < 30) {
    guard++;
    let page;
    try { page = await buscarPagina(cursor); } catch (_) { break; }
    const pdata = (page && page.data) ? page.data : [];
    if (!Array.isArray(pdata) || pdata.length === 0) break;
    brutos = brutos.concat(pdata);
    cursor = (page && page.nextCursor) || null;
  }
}
const disponiveis = brutos.filter(item => {
  if (item && item.sending === true) return false;
  const sa = String((item && item.sent_at) || "").trim();
  if (sa.startsWith("__CLAIM__")) return false;      // reserva ativa de outra execucao
  if (sa && !sa.startsWith("__") && Number.isFinite(Date.parse(sa))) return false; // envio real
  return true;
});
if (disponiveis.length === 0) return [{ json: { skipped: "sem produto novo no data table - aguardando scraper" } }];

const isMercadoLivre = /mercado/i.test(String(PLATAFORMA || ""));
function rowValido(item) {
  const link = String((item && item.offerlink) || "").trim();
  if (isMercadoLivre && !/^https?:\/\/meli\.la\//i.test(link)) return false;
  return true; // sent_at REAL nao bloqueia mais (re-listagem e normal); reenvio quem decide e a dedupe 45d. Claim e tratado em escolher().
}
// passou do limite de tentativas? descarta pra não travar a fila
function estourouTentativas(item) { return (Number(sd.fails[item && item.id]) || 0) >= MAX_TENTATIVAS_ENVIO; }

let linkInvalido = 0, claimAtivo = 0, dedupeSkips = 0; // diagnostico (aparece no output)
async function escolher(lista) {
  for (const item of lista) {
    if (!rowValido(item)) { linkInvalido++; continue; }                                  // link nao-meli.la
    if (String((item && item.sent_at) || "").trim().startsWith("__CLAIM__:")) { claimAtivo++; continue; } // reserva ativa de outra execucao
    if (estourouTentativas(item)) { await queimaRow(item.id); delete sd.fails[item.id]; continue; }
    if (localJaFoiEnviado(item)) { dedupeSkips++; await patchRow(item.id, { sending: true, sent_at: "__DEDUPE__:" + new Date().toISOString() }); continue; } // ja enviado (local) -> queima a linha pra nao virar zumbi
    // GATE PERSISTENTE (Postgres robo_produtos_enviados): sobrevive a reset de workflow/staticData.
    // Reativado — era a unica trava capaz de barrar re-listagem com link/shortlink novo.
    if (await jaFoiEnviado(item)) { dedupeSkips++; await patchRow(item.id, { sending: true, sent_at: "__DEDUPE__:" + new Date().toISOString() }); continue; }
    return item;
  }
  return null;
}

// 6. Seleção: rodízio por categoria (cai pra sequencial se não houver categoria)
const temCategoria = disponiveis.some(c => normCat(c[COL_CATEGORIA]) !== "");
let row = null;
if (!temCategoria) {
  row = await escolher(disponiveis);
} else {
  const grupos = {};
  for (const c of disponiveis) { const cat = normCat(c[COL_CATEGORIA]) || "_sem_categoria"; (grupos[cat] = grupos[cat] || []).push(c); }
  for (const cat of Object.keys(grupos)) grupos[cat].sort((a, b) => (Number(a.id) || 0) - (Number(b.id) || 0));
  const ciclo = Object.keys(grupos).sort();
  if (ultimaCat && !ciclo.includes(ultimaCat)) ciclo.push(ultimaCat);
  const idxUlt = ultimaCat ? ciclo.indexOf(ultimaCat) : -1;
  const start = idxUlt >= 0 ? idxUlt + 1 : 0;
  for (let k = 0; k < ciclo.length; k++) {
    const cat = ciclo[(start + k) % ciclo.length];
    const escolhido = await escolher(grupos[cat] || []);
    if (escolhido) { row = escolhido; break; }
  }
}
if (!row) return [{ json: { skipped: "nenhum produto enviavel agora", motivo: "ja enviados nos ultimos 45 dias (dedupe) ou link invalido", dedupe_skipped: dedupeSkips, link_invalido: linkInvalido, claim_ativo: claimAtivo, disponiveis: disponiveis.length } }];

// 7. RESERVA ATÔMICA: marca sending=true ANTES de enviar (evita duas execuções pegarem a mesma linha)
const claimToken = "__CLAIM__:" + Date.now() + ":" + Math.random().toString(36).slice(2);
await patchRow(row.id, { sending: true, sent_at: claimToken }); // só p/ travar; vira data real no fim
try {
  const check = await http({ method:"GET", url:`${N8N_BASE}/data-tables/${TABLE_ID}/rows`,
    qs:{ filter: JSON.stringify({ type:"and", filters:[{ columnName:"id", condition:"eq", value:row.id }] }), limit:1 },
    headers:{ "X-N8N-API-KEY": N8N_KEY }, json:true });
  const atual = (check && check.data && check.data[0]) || null;
  const reservadoPorMim = atual && atual.sending === true && String(atual.sent_at || "") === claimToken;
  if (!reservadoPorMim) return [{ json: { skipped: "linha ja reservada por outra execucao - evitando duplicidade" } }];
} catch (_) {}

// 8. Frase curta por IA (Lovable AI / Gemini Flash Lite) — com fallback se falhar
let frase = "OFERTA IMPERDÍVEL";
let fraseDebug = "no-key";
if (LOVABLE_API_KEY) {
  fraseDebug = "called";
  try {
    const aiResp = await http({
      method: "POST", url: "https://ai.gateway.lovable.dev/v1/chat/completions",
      headers: { "Authorization": "Bearer " + LOVABLE_API_KEY, "Content-Type": "application/json" },
      body: {
        model: "google/gemini-2.5-flash-lite",
        messages: [
          { role: "system", content: "Você é um copy de marketing brasileiro. Gere UMA frase curtíssima em CAIXA ALTA (2 a 4 palavras, sem aspas, sem pontuação final, sem emoji, sem hashtag) ESPECÍFICA para o produto informado — destaque uma qualidade real do produto. Exemplos: ESSE É VERSÁTIL / PRA QUEM AMA CHURRASCO / TÁ MUITO BARATO / DESIGN INCRÍVEL / SÓ HOJE. NUNCA responda apenas 'OFERTA IMPERDÍVEL'. Responda APENAS a frase, nada mais." },
          { role: "user", content: "Produto: " + String(row.productname || "") },
        ],
        max_tokens: 60, temperature: 0.95,
      },
      json: true, timeout: 12000,
    });
    const txt = String(aiResp && aiResp.choices && aiResp.choices[0] && aiResp.choices[0].message && aiResp.choices[0].message.content || "").trim();
    const cleaned = txt.replace(/["'`*_#]/g, "").replace(/[\.!?,;:]+$/g, "").trim().toUpperCase();
    if (cleaned && cleaned.length <= 60) { frase = cleaned; fraseDebug = "ok:" + cleaned; }
    else { fraseDebug = "empty"; }
  } catch (e) { fraseDebug = "err:" + String(e && e.message || e).slice(0, 120); }
}
console.log("FRASE_IA", fraseDebug);

// 9. Monta legenda
function fmtBRL(n) { const v = Number(n) || 0; return v.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
const priceNum = Number(row.price) || 0;
const discNum = Number(row.pricediscountrate) || 0;
let priceOriginalNum = Number(row.priceoriginal) || 0;
if (!priceOriginalNum && priceNum > 0 && discNum > 0 && discNum < 100) priceOriginalNum = priceNum / (1 - discNum / 100);
if (priceOriginalNum && priceNum && priceOriginalNum <= priceNum) priceOriginalNum = 0;
// Sem preco original REAL: nao inventa "De X por X" — remove a linha do preco antigo
// e o sufixo de % OFF do template.
let TPL = TEMPLATE;
if (!(priceOriginalNum > 0)) {
  TPL = TPL.replace(/^.*\{priceoriginal\}.*\n?/gm, "");
}
if (!(discNum > 0)) {
  TPL = TPL.replace(/\s*\(\s*\{pricediscountrate\}\s*%?\s*OFF\s*\)/gi, "");
  TPL = TPL.replace(/\{pricediscountrate\}/g, "");
}
TPL = TPL.replace(/\n{3,}/g, "\n\n");
const shortLink = String(row.offerlink || "");
const caption = TPL
  .replace(/\{frase\}/g, frase)
  .replace(/\{productname\}/g, String(row.productname == null ? "" : row.productname))
  .replace(/\{price\}/g, fmtBRL(priceNum))
  .replace(/\{priceoriginal\}/g, fmtBRL(priceOriginalNum))
  .replace(/\{pricediscountrate\}/g, String(discNum || ""))
  .replace(/\{shopname\}/g, String(row.shopname == null ? "" : row.shopname))
  .replace(/\{offerlink\}/g, shortLink)
  .replace(/\{imageUrl\}/g, String(row.imageUrl == null ? "" : row.imageUrl));

const grupo = DESTINOS[Math.floor(Math.random() * DESTINOS.length)];

// 10. Envia via Evolution (media URL → base64 → texto). Captura o erro REAL de cada etapa.
const imgUrl = String(row.imageUrl || "").trim();
const hasImg = /^https?:\/\//i.test(imgUrl);
function errStatus(e) {
  const s = (e && (e.statusCode || e.httpCode || (e.response && (e.response.statusCode || e.response.status))));
  const num = Number(s);
  return Number.isFinite(num) ? num : 0;
}
// So troca de metodo de envio quando a Evolution REJEITOU a requisicao de forma
// clara (4xx). Timeout / erro de rede / 5xx sao AMBIGUOS: a mensagem pode ter sido
// entregue e tentar outro metodo gera a MESMA promo 2x/3x no grupo.
function podeTentarOutroMetodo(e) {
  const st = errStatus(e);
  return st >= 400 && st < 500;
}
function errBody(e) {
  const b = e && e.response && (e.response.body || e.response.data);
  if (b) return typeof b === "string" ? b : JSON.stringify(b);
  return (e && e.message) ? e.message : String(e);
}
async function fetchImageBase64(url) {
  const buf = await http({ method:"GET", url, headers:{ "user-agent":"Mozilla/5.0", "accept":"image/*,*/*" }, encoding:"arraybuffer", returnFullResponse:false });
  const b = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
  return b.toString("base64");
}
async function tryMediaUrl() {
  return await http({ method:"POST", url:`${EVO_URL}/message/sendMedia/${INSTANCE}`, headers:{ "apikey":EVO_KEY, "Content-Type":"application/json" },
    body:{ number:grupo, mediatype:"image", mimetype:"image/jpeg", media:imgUrl, caption, fileName:"promo.jpg" }, json:true });
}
async function tryMediaBase64() {
  const b64 = await fetchImageBase64(imgUrl);
  return await http({ method:"POST", url:`${EVO_URL}/message/sendMedia/${INSTANCE}`, headers:{ "apikey":EVO_KEY, "Content-Type":"application/json" },
    body:{ number:grupo, mediatype:"image", mimetype:"image/jpeg", media:b64, caption, fileName:"promo.jpg" }, json:true });
}
async function tryText() {
  return await http({ method:"POST", url:`${EVO_URL}/message/sendText/${INSTANCE}`, headers:{ "apikey":EVO_KEY, "Content-Type":"application/json" },
    body:{ number:grupo, text: caption + (hasImg ? "\n\n" + imgUrl : "") }, json:true });
}

let sendOk = false, sendVia = null, sendErr = null, ambiguo = false;
if (hasImg) {
  try { await tryMediaUrl(); sendOk = true; sendVia = "media_url"; }
  catch (e1) {
    const d1 = errBody(e1);
    if (!podeTentarOutroMetodo(e1)) {
      ambiguo = true;
      sendErr = "media_url AMBIGUO (timeout/rede/5xx) - sem retry p/ nao duplicar: " + d1;
    } else {
      try { await tryMediaBase64(); sendOk = true; sendVia = "media_base64"; sendErr = "media_url falhou: " + d1; }
      catch (e2) {
        const d2 = errBody(e2);
        if (!podeTentarOutroMetodo(e2)) {
          ambiguo = true;
          sendErr = "media_base64 AMBIGUO (timeout/rede/5xx) - sem retry p/ nao duplicar: " + d2;
        } else {
          try { await tryText(); sendOk = true; sendVia = "text_fallback"; sendErr = "media falhou (url: " + d1 + " | b64: " + d2 + ") \u2192 enviado como TEXTO"; }
          catch (e3) {
            const d3 = errBody(e3);
            if (!podeTentarOutroMetodo(e3)) ambiguo = true;
            sendErr = "TUDO FALHOU \u2192 media_url: " + d1 + " | media_b64: " + d2 + " | text: " + d3;
          }
        }
      }
    }
  }
} else {
  try { await tryText(); sendOk = true; sendVia = "text"; }
  catch (e) {
    const de = errBody(e);
    if (!podeTentarOutroMetodo(e)) { ambiguo = true; sendErr = "text AMBIGUO (timeout/rede/5xx) - sem retry p/ nao duplicar: " + de; }
    else sendErr = "text falhou: " + de;
  }
}
console.log("ENVIO", JSON.stringify({ ok: sendOk, via: sendVia, ambiguo: ambiguo, erro: sendErr, produto: row.productname }));

// 11. Resolve a linha conforme o resultado
if (sendOk) {
  await registrarEnviado(row, grupo);                                   // histórico SÓ no sucesso
  await patchRow(row.id, { sending: true, sent_at: new Date().toISOString() });
  delete sd.fails[row.id];
  sd.lastSentMs = Date.now();                                           // gate do intervalo: só conta envio REAL
} else if (ambiguo) {
  // Pode ter sido entregue no grupo. Trata como enviado: nao reenvia e nao libera a linha.
  await registrarEnviado(row, grupo);
  await patchRow(row.id, { sending: true, sent_at: new Date().toISOString() });
  delete sd.fails[row.id];
  sd.lastSentMs = Date.now();
} else {
  const n = (Number(sd.fails[row.id]) || 0) + 1;
  sd.fails[row.id] = n;
  if (n >= MAX_TENTATIVAS_ENVIO) {
    await patchRow(row.id, { sending: true, sent_at: new Date().toISOString() });  // desiste p/ não travar a fila
    delete sd.fails[row.id];
  } else {
    await patchRow(row.id, { sending: false, sent_at: "" });             // LIBERA p/ tentar de novo
  }
}

// 12. Atualiza estado do robô
try {
  await http({ method:"POST", url:SCRAPPER_API, headers:{ "Authorization":"Bearer " + SCRAPPER_SECRET, "Content-Type":"application/json" },
    body: sendOk
      ? { action:"update_campanha", id:ROBO_ID, total_enviados:1, intervalo_dia:intervaloMin }
      : { action:"update_campanha", id:ROBO_ID, ultimo_erro:(sendErr || "falha envio Evolution").slice(0,500), intervalo_dia:intervaloMin },
    json:true });
} catch (_) {}

// 13. Output VISÍVEL na execução (inclui o erro real do Evolution)
return [{ json: {
  ok: sendOk,
  ambiguo: ambiguo,
  enviado: sendOk ? row.productname : null,
  via: sendVia,
  frase,
  produto: row.productname,
  grupo, dia: diaKey, intervalo: intervaloMin,
  tentativas_acumuladas: sd.fails[row.id] || 0,
  dedupe_skipped: dedupeSkips,
  link_invalido: linkInvalido,
  claim_ativo: claimAtivo,
  erro: sendErr,
} }];
